// ═══ PROBLEM: daemon threads → silently lost ═══
public static void main(String[] args) {
    CompletableFuture.runAsync(() -> {
        settleTrade("TRD-001");  // takes 5 seconds
    });
    // main() returns → JVM checks: any non-daemon threads? NO!
    // ForkJoinPool workers are DAEMON → JVM exits!
    // settleTrade("TRD-001") killed mid-execution → LOST!
    // No exception. No log. No retry. SILENT!
}

// ═══ FIX 1: non-daemon pool + graceful shutdown ═══
ThreadPoolExecutor pool = new ThreadPoolExecutor(
    10, 20, 60, TimeUnit.SECONDS,
    new LinkedBlockingQueue<>(1000),
        r -> { Thread t = new Thread(r); t.setDaemon(false);
        return t; }  // NON-daemon!
);
// Non-daemon threads keep JVM alive!
// But MUST call shutdown:
Runtime.getRuntime().addShutdownHook(new Thread(() -> {
    pool.shutdown();
    try { pool.awaitTermination(30, TimeUnit.SECONDS); }
    catch (InterruptedException e) { pool.shutdownNow(); }
}));

