package com.bank.durable;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class DurableAsyncTest {

    // ═══ Default pool (daemon) — tasks lost on JVM exit ═══
    @Test
    void defaultPool_isDaemon() throws InterruptedException {
        AtomicBoolean isDaemon = new AtomicBoolean(false);
        CountDownLatch done = new CountDownLatch(1);

        CompletableFuture.runAsync(() -> {
            isDaemon.set(Thread.currentThread().isDaemon());
            done.countDown();
        });
        done.await();

        assertThat(isDaemon.get()).isTrue();  // DAEMON! Lost on JVM exit!
    }

    // ═══ Custom non-daemon pool — tasks survive ═══
    @Test
    void customPool_nonDaemon() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(2, r -> {
            Thread t = new Thread(r);
            t.setDaemon(false);  // non-daemon!
            return t;
        });
        AtomicBoolean isDaemon = new AtomicBoolean(true);
        CountDownLatch done = new CountDownLatch(1);

        CompletableFuture.runAsync(() -> {
            isDaemon.set(Thread.currentThread().isDaemon());
            done.countDown();
        }, pool);
        done.await();

        assertThat(isDaemon.get()).isFalse();  // non-daemon! JVM waits!
        pool.shutdown();
    }

    // ═══ Graceful shutdown: wait for tasks ═══
    @Test
    void gracefulShutdown_waitsForTasks() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        AtomicInteger completed = new AtomicInteger(0);

        for (int i = 0; i < 5; i++) {
            pool.submit(() -> {
                try { Thread.sleep(100); } catch (InterruptedException e) {
                    Thread.currentThread().interrupt(); return;
                }
                completed.incrementAndGet();
            });
        }

        pool.shutdown();  // stop accepting new tasks
        boolean terminated = pool.awaitTermination(10, TimeUnit.SECONDS);

        assertThat(terminated).isTrue();
        assertThat(completed.get()).isEqualTo(5);  // ALL completed!
    }

    // ═══ Simulating the outbox pattern (simplified) ═══
    @Test
    void outboxPattern_neverLost() {
        // Simulated outbox: in real code this is a DB table
        ConcurrentLinkedQueue<String> outbox = new ConcurrentLinkedQueue<>();

        // Business logic + outbox write (in same "transaction"):
        String tradeId = "TRD-001";
        outbox.add(tradeId);  // "persisted" — survives crash!

        // Poller processes outbox:
        String task = outbox.poll();
        assertThat(task).isEqualTo("TRD-001");
        // Even if JVM crashes after outbox.add() but before processing:
        // Entry is in DB → restart → poller retries → zero lost!
    }
}
